const state={view:'rollcall',students:[],history:[],absences:[],exams:[],examResults:[],settings:{},candidates:[],selectedCandidate:null,currentClass:'',difficulty:3,source:'',pendingImport:null,studentSort:'score-desc',studentDetail:null,statsMode:'timeline',historyStudentId:'',studentCurrentExamId:'',studentPreviousExamId:''};
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
function toast(message){const el=$('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),2600);}
function localDate(){const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;}
function relativeCallTime(at){const stamp=Date.parse(at);if(!Number.isFinite(stamp))return '—';const today=new Date();today.setHours(0,0,0,0);const day=new Date(stamp);day.setHours(0,0,0,0);const days=Math.max(0,Math.round((today-day)/86400000));return days===0?'今天':`${days}天前`;}
function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function classes(){return [...new Set(state.students.map(s=>normalizeClassName(s.className)).filter(c=>c&&c!=='未分班'))].sort();}
async function reload(){[state.students,state.history,state.absences,state.exams,state.examResults]=await Promise.all([DB.all('students'),DB.all('history'),DB.all('absences'),DB.all('exams'),DB.all('examResults')]);state.students.forEach(s=>{s.className=normalizeClassName(s.className);s.id=s.id||`${s.className}-${s.name}`;});state.examResults.forEach(r=>{if(r.result){r.result.className=normalizeClassName(r.result.className);r.identityKey=r.identityKey||`${r.result.className}-${r.result.name}`;}});for(const exam of state.exams){const storedTotal=Number(exam.totalScore);if(Number.isFinite(storedTotal)&&storedTotal>100)continue;const max=Math.max(...state.examResults.filter(r=>r.examId===exam.id).map(r=>Number(r.result?.score)||0),0);if(max>100){const repaired=[120,150,160,180,200].find(n=>max<=n)||Math.ceil(max/10)*10;exam.totalScore=repaired;await DB.put('exams',exam);}} state.settings=mergeConfig(await DB.getSettings()); state.currentClass=state.currentClass?normalizeClassName(state.currentClass):classes()[0]||'';const exams=orderedExams();if(!exams.some(e=>e.id===state.studentCurrentExamId))state.studentCurrentExamId=exams[0]?.id||'';if(!exams.some(e=>e.id===state.studentPreviousExamId)||state.studentPreviousExamId===state.studentCurrentExamId)state.studentPreviousExamId=exams.find(e=>e.id!==state.studentCurrentExamId)?.id||''; render();}
function render(){ const globalSelect=$('#globalClassSelect');if(globalSelect){globalSelect.innerHTML=classes().map(c=>`<option value="${esc(c)}" ${c===state.currentClass?'selected':''}>${esc(c)}</option>`).join('')||'<option value="">暂无班级</option>';globalSelect.onchange=()=>{state.currentClass=globalSelect.value;state.selectedCandidate=null;state.candidates=[];state.studentDetail=null;render();};} const quick=$('#quickClasses');if(quick){quick.innerHTML=(state.settings.shortcutClasses||[]).map(c=>`<button class="secondary quick-class" data-quick-class="${esc(c)}">${esc(c)}</button>`).join('');$$('[data-quick-class]').forEach(b=>b.addEventListener('click',()=>{state.currentClass=b.dataset.quickClass;state.selectedCandidate=null;state.candidates=[];state.studentDetail=null;render();}));} $$('.view').forEach(x=>x.classList.toggle('active',x.id===`view-${state.view}`)); $$('.tab').forEach(x=>x.classList.toggle('active',x.dataset.view===state.view)); ({rollcall:renderRollcall,students:renderStudents,history:renderHistory,data:renderData,settings:renderSettings}[state.view])(); }
function renderRollcall(){const inClass=state.students.filter(s=>s.className===state.currentClass);const candidates=state.candidates;const currentExam=orderedExams()[0];const difficultyLabel=['','简单','适中','困难'][state.difficulty]||'适中';$('#view-rollcall').innerHTML=`<div class="panel hero"><div class="class-name">${inClass.length?`本班 ${inClass.length} 人`:'还没有学生资料'}</div><div class="field"><label>题目难度</label><div class="difficulty-buttons"><button class="secondary difficulty-button ${!state.selectedCandidate&&state.difficulty===1?'active':''}" data-difficulty="1">简单</button><button class="secondary difficulty-button ${!state.selectedCandidate&&state.difficulty===2?'active':''}" data-difficulty="2">适中</button><button class="secondary difficulty-button ${!state.selectedCandidate&&state.difficulty===3?'active':''}" data-difficulty="3">困难</button></div></div><div class="question">${state.selectedCandidate?'单击难度按钮继续点名':'选择难度后生成候选'}</div></div><div class="panel"><h2>本次候选</h2><p class="hint">点击学生表示正式点名；只有选中后才会保留该学生。</p><div class="candidate-list">${candidates.length?candidates.map(c=>{const current=examResult(currentExam,c.student)||c.student;return `<button class="candidate ${state.selectedCandidate===c.student.id?'selected-candidate':''}" data-student="${esc(c.student.id)}"><span><strong>${esc(c.student.displayName||c.student.name)}</strong><small>当前 ${current.score??'—'}分 · 班次 ${current.classRank??'—'}</small></span><span class="score">${difficultyLabel} · 最近${state.settings.historyWindow}次：${c.recentCount}次</span></button>`}).join(''):'<div class="empty">选择上方难度后生成候选</div>'}</div></div>`;$$('[data-difficulty]').forEach(b=>b.addEventListener('click',()=>{state.difficulty=Number(b.dataset.difficulty);state.selectedCandidate=null;recommend();}));$$('.candidate').forEach(b=>b.addEventListener('click',()=>selectStudent(b.dataset.student)));}
function recommend(){state.settings.currentDifficulty=state.difficulty;const currentExam=orderedExams()[0];const pool=state.students.filter(s=>s.className===state.currentClass).map(s=>({...s,...(examResult(currentExam,s)||{}),scoreRate:averageScoreRate(s)}));state.candidates=chooseCandidates(pool,state.history,state.absences,{...state.settings,currentDifficulty:state.difficulty});renderRollcall();}
async function selectStudent(id){const s=state.students.find(x=>x.id===id);if(!s)return;await DB.put({studentId:id,at:new Date().toISOString(),difficulty:state.difficulty,className:state.currentClass});state.selectedCandidate=id;await reload();state.selectedCandidate=id;state.candidates=[{student:state.students.find(x=>x.id===id),recentCount:recentHistoryEntries(state.history,id,state.settings).length}];renderRollcall();toast(`已点名：${s.name}`);}
function orderedExams(){return [...state.exams].sort((a,b)=>String(b.date).localeCompare(String(a.date))||String(b.importedAt).localeCompare(String(a.importedAt)));}
function chronologicalExams(){return [...state.exams].sort((a,b)=>String(a.date).localeCompare(String(b.date))||String(a.importedAt).localeCompare(String(b.importedAt)));}
function studentKey(student){const name=String(student?.name??'').trim().replace(/\s+/g,'');const nums=String(student?.className??'').match(/\d+/g);const cls=nums?.length?nums[nums.length-1]:String(student?.className??'').trim();return `${name}|${cls}`;}
function examResult(exam,student){if(!exam||!student)return null;const key=studentKey(student);const match=state.examResults.find(r=>r.examId===exam.id&&(r.studentId===student.id||r.identityKey===key||studentKey(r.result)===key));return match?.result||null;}
function examScoreRate(exam,result){if(!exam||!result)return null;const score=Number(result.score);const total=Number(exam.totalScore)||100;return Number.isFinite(score)&&total>0?Math.max(0,Math.min(1,score/total)):null;}
function averageScoreRate(student){const count=Number(state.settings.basisExamCount)||3;const exams=orderedExams().slice(0,count);let weighted=0,totalWeight=0;for(const exam of exams){const result=examResult(exam,student);const rate=examScoreRate(exam,result);const weight=Math.max(0,Number(exam.weight??1));if(rate!==null&&weight>0){weighted+=rate*weight;totalWeight+=weight;}}return totalWeight?weighted/totalWeight:null;}
function averageRankMap(students){const ranked=students.map(s=>({id:s.id,rate:averageScoreRate(s)})).sort((a,b)=>{if(a.rate===null&&b.rate===null)return String(a.id).localeCompare(String(b.id));if(a.rate===null)return 1;if(b.rate===null)return -1;return b.rate-a.rate||String(a.id).localeCompare(String(b.id));});return new Map(ranked.map((x,i)=>[x.id,x.rate===null?null:i+1]));}
function examOptions(selected){return orderedExams().map(e=>`<option value="${esc(e.id)}" ${e.id===selected?'selected':''}>${esc(e.name||e.date)}</option>`).join('')||'<option value="">暂无考试</option>';}
function rankNumber(value){const n=Number(String(value??'').replace(/[^0-9.-]/g,''));return Number.isFinite(n)?n:null;}
function rankDelta(current,previous){const now=rankNumber(current),old=rankNumber(previous);if(now===null||old===null)return '';const delta=now-old;if(delta===0)return '<span class="rank-same">（持平）</span>';return delta>0?`<span class="rank-down">（↓${delta}）</span>`:`<span class="rank-up">（↑${Math.abs(delta)}）</span>`;}
function studentSortValue(student){const exams=orderedExams(),latest=examResult(exams[0],student),previous=examResult(exams[1],student);if(state.studentSort.startsWith('score'))return Number(latest?.score??-1);if(state.studentSort.startsWith('average'))return Number(averageScoreRate(student)??-1);const current=rankNumber(latest?.gradeRank),old=rankNumber(previous?.gradeRank);return current===null||old===null?null:old-current;}
function sortedStudents(rows){const direction=state.studentSort.endsWith('asc')?1:-1;return [...rows].sort((a,b)=>{const av=studentSortValue(a),bv=studentSortValue(b);if(state.studentSort.startsWith('rank')){if(av===null&&bv!==null)return 1;if(av!==null&&bv===null)return -1;}return ((av??0)-(bv??0))*direction||String(a.name).localeCompare(String(b.name),'zh-CN');});}
function toggleStudentSort(group){const prefix=group==='score'?'score':group==='average'?'average':'rank';state.studentSort=state.studentSort.startsWith(prefix)&&state.studentSort.endsWith('desc')?`${prefix}-asc`:`${prefix}-desc`;renderStudents();}
function bindStudentActions(){ $$('#scoreSortBtn').forEach(b=>b.addEventListener('click',()=>toggleStudentSort('score'))); $$('#rankSortBtn').forEach(b=>b.addEventListener('click',()=>toggleStudentSort('rank'))); $$('[data-student-detail]').forEach(b=>b.addEventListener('click',()=>{state.studentDetail=b.dataset.studentDetail;renderStudents();})); $$('[data-focus]').forEach(b=>b.addEventListener('click',async()=>{const s=state.students.find(x=>x.id===b.dataset.focus);s.focus=!s.focus;await DB.put(s);renderStudents();})); $$('[data-absent]').forEach(b=>b.addEventListener('click',async()=>{const existing=state.absences.find(x=>x.studentId===b.dataset.absent&&x.date===localDate());if(existing)await DB.put({...existing,remove:true});else await DB.put({id:`${b.dataset.absent}-${localDate()}`,studentId:b.dataset.absent,date:localDate()});state.absences=(await DB.all('absences')).filter(x=>!x.remove);await DB.replace('absences',state.absences);renderStudents();})); }
function renderStudents(){if(state.studentDetail){renderStudentDetail(state.studentDetail);return;}const filtered=state.students.filter(s=>!state.currentClass||s.className===state.currentClass);const scoreLabel=state.studentSort==='score-desc'?'成绩：由高到低':'成绩：由低到高';const rankLabel=state.studentSort==='rank-desc'?'段次变化：由高到低':'段次变化：由低到高';const exams=orderedExams();$('#view-students').innerHTML=`<div class="panel"><div class="grid"><div class="field"><label>当前考试</label><select id="studentCurrentExam">${examOptions(state.studentCurrentExamId)}</select></div><div class="field"><label>上一次考试</label><select id="studentPreviousExam">${examOptions(state.studentPreviousExamId)}</select></div></div><div class="field"><label>搜索姓名</label><input id="studentSearch" placeholder="输入姓名"></div><div class="actions"><button class="secondary" id="scoreSortBtn">${scoreLabel}</button><button class="secondary" id="rankSortBtn">${rankLabel}</button></div></div><div class="panel"><h2>学生资料 <span class="badge">${filtered.length}人</span></h2><div id="studentList">${studentRows(filtered)}</div></div>`;$('#studentCurrentExam')?.addEventListener('change',e=>{state.studentCurrentExamId=e.target.value;renderStudents();});$('#studentPreviousExam')?.addEventListener('change',e=>{state.studentPreviousExamId=e.target.value;renderStudents();});$('#studentSearch')?.addEventListener('input',e=>{$('#studentList').innerHTML=studentRows(filtered.filter(s=>String(s.name||'').includes(e.target.value.trim())));bindStudentActions();});bindStudentActions();}
function rankColor(rank,max){const ratio=max?Math.max(0,Math.min(1,(rank-1)/(max-1||1))):0;return ratio<.33?'#dcfce7':ratio<.66?'#fef3c7':'#fee2e2';}
function studentRows(rows){if(!rows.length)return '<div class="empty">暂无学生</div>';const exams=orderedExams(),currentExam=exams.find(e=>e.id===state.studentCurrentExamId)||exams[0],previousExam=exams.find(e=>e.id===state.studentPreviousExamId)||exams[1],hasComparison=Boolean(previousExam&&currentExam&&previousExam.id!==currentExam.id);return sortedStudents(rows).map(s=>{const absent=state.absences.some(a=>a.studentId===s.id&&a.date===localDate());const latest=examResult(currentExam,s),previous=examResult(previousExam,s),l=latest||{},display=l.displayName||s.displayName||s.name;return `<div class="stat-row student-row"><span><button class="student-link" data-student-detail="${esc(s.id)}">${esc(display)}</button><br><small class="hint">${esc(s.className)} · ${latest?`${l.score}分`:'缺考'}</small></span><span class="rank-info">班次：${latest?(l.classRank??'—'):'—'} ${hasComparison&&latest?rankDelta(l.classRank,previous?.classRank):''}<br>段次：${latest?(l.gradeRank??'—'):'—'} ${hasComparison&&latest?rankDelta(l.gradeRank,previous?.gradeRank):''}<br>${s.focus?'<span class="badge">关注</span>':''}${absent?'<span class="badge absence-badge">缺席</span>':''}</span><span><button class="secondary" data-focus="${esc(s.id)}">${s.focus?'取消关注':'关注'}</button><button class="absence-action" data-absent="${esc(s.id)}">${absent?'恢复出勤':'缺席'}</button></span></div>`}).join('');}
function renderStudentDetail(id){const s=state.students.find(x=>x.id===id);if(!s){state.studentDetail=null;renderStudents();return;}const exams=chronologicalExams();const records=exams.map(e=>({exam:e,result:examResult(e,s)})).filter(x=>x.result);const maxClass=Math.max(...state.examResults.map(x=>rankNumber(x.result?.classRank)||0),1),maxGrade=Math.max(...state.examResults.map(x=>rankNumber(x.result?.gradeRank)||0),1),current=records[records.length-1]?.result,display=current?.displayName||s.displayName||s.name;$('#view-students').innerHTML=`<div class="panel"><div class="detail-header"><button class="secondary" id="backStudents">返回学生列表</button><h2>${esc(display)}</h2></div><p class="hint">${esc(s.className)} · 当前考试成绩：${current?.score??'—'}分</p></div><div class="panel"><h3>全部考试记录</h3>${records.length?records.map(x=>`<div class="stat-row"><span><strong>${esc(x.exam.name)}</strong><br><small class="hint">考试时间：${esc(x.exam.date)}</small></span><span><strong>${x.result.score}分</strong></span><span class="rank-cell"><span style="background:${rankColor(Number(x.result.classRank)||maxClass,maxClass)}" class="rank-chip">班 ${x.result.classRank??'—'}</span><span style="background:${rankColor(Number(x.result.gradeRank)||maxGrade,maxGrade)}" class="rank-chip">段 ${x.result.gradeRank??'—'}</span></span></div>`).join(''):'<div class="empty">暂无考试记录</div>'}</div><div class="panel"><h3>成绩趋势</h3><div class="chart-wrap"><canvas id="scoreChart" width="760" height="280"></canvas></div></div>`;$('#backStudents').addEventListener('click',()=>{state.studentDetail=null;renderStudents();});drawScoreChart(s,records);}
function drawScoreChart(student,records){const canvas=$('#scoreChart');if(!canvas||!records.length)return;const ctx=canvas.getContext('2d'),w=canvas.width,h=canvas.height,p=38;ctx.clearRect(0,0,w,h);const scores=records.map(x=>Number(x.result.score)||0),avg=records.map(x=>{const vals=state.examResults.filter(r=>r.examId===x.exam.id).map(r=>Number(r.result?.score)).filter(Number.isFinite);return vals.length?vals.reduce((a,b)=>a+b,0)/vals.length:0;}),max=Math.max(100,...scores,...avg);ctx.strokeStyle='#dfe9e6';ctx.lineWidth=1;for(let y=0;y<=4;y++){const yy=p+(h-p*2)*y/4;ctx.beginPath();ctx.moveTo(p,yy);ctx.lineTo(w-p,yy);ctx.stroke();}const pointX=i=>p+(w-p*2)*(records.length===1?.5:i/(records.length-1)),pointY=v=>h-p-(h-p*2)*(v/max),formatValue=v=>Number.isInteger(v)?String(v):v.toFixed(1);const line=(vals,color,labelOffset)=>{ctx.strokeStyle=color;ctx.lineWidth=3;ctx.beginPath();vals.forEach((v,i)=>{const x=pointX(i),y=pointY(v);i?ctx.lineTo(x,y):ctx.moveTo(x,y);});ctx.stroke();vals.forEach((v,i)=>{const x=pointX(i),y=pointY(v);ctx.fillStyle=color;ctx.beginPath();ctx.arc(x,y,4,0,Math.PI*2);ctx.fill();ctx.fillStyle=color;ctx.font='12px sans-serif';ctx.textAlign='center';ctx.fillText(formatValue(v),x,y+labelOffset);});};line(avg,'#16302b',-9);line(scores,'#b42318',16);ctx.fillStyle='#16302b';ctx.font='12px sans-serif';ctx.textAlign='center';records.forEach((record,i)=>ctx.fillText(record.exam.date,pointX(i),h-12));ctx.textAlign='left';ctx.fillText('班级均分',p,18);ctx.fillStyle='#b42318';ctx.fillText('个人得分',p+90,18);}
function drawDifficultyPie(counts){const canvas=$('#difficultyChart');if(!canvas)return;const ctx=canvas.getContext('2d'),w=canvas.width,h=canvas.height,cx=w/2,cy=h/2,r=Math.min(w,h)*.34,total=counts.reduce((sum,n)=>sum+n,0),colors=['#2f80ed','#f2c94c','#eb5757'];ctx.clearRect(0,0,w,h);if(!total){ctx.fillStyle='#6b7c78';ctx.font='14px sans-serif';ctx.textAlign='center';ctx.fillText('暂无点名数据',cx,cy);ctx.textAlign='left';return;}let start=-Math.PI/2;counts.forEach((count,i)=>{const angle=count/total*Math.PI*2;ctx.beginPath();ctx.moveTo(cx,cy);ctx.arc(cx,cy,r,start,start+angle);ctx.closePath();ctx.fillStyle=colors[i];ctx.fill();start+=angle;});ctx.fillStyle='#fff';ctx.beginPath();ctx.arc(cx,cy,r*.52,0,Math.PI*2);ctx.fill();ctx.fillStyle='#16302b';ctx.font='bold 15px sans-serif';ctx.textAlign='center';ctx.fillText(`${total}次`,cx,cy+5);ctx.textAlign='left';}
async function renderHistory(){const window=state.settings.historyWindow||20;const counts=new Map();state.history.slice(-window).forEach(x=>counts.set(x.studentId,(counts.get(x.studentId)||0)+1));const rows=[...state.students].sort((a,b)=>(counts.get(b.id)||0)-(counts.get(a.id)||0));const timeline=[...state.history].sort((a,b)=>String(b.at).localeCompare(String(a.at)));$('#view-history').innerHTML=`<div class="panel"><div class="stats-switch"><button class="secondary ${state.statsMode==='timeline'?'active':''}" id="timelineBtn">点名时间</button><button class="secondary ${state.statsMode==='counts'?'active':''}" id="countsBtn">学生总次数</button></div><div class="grid"><div class="field"><label>统计窗口</label><select id="historyWindow">${[20,50,100,'all'].map(x=>`<option value="${x}" ${String(window)===String(x)?'selected':''}>${x==='all'?'全部历史':`最近${x}次`}</option>`).join('')}</select></div><div class="field"><label>总点名次数</label><input disabled value="${state.history.length}"></div></div></div>${state.statsMode==='timeline'?`<div class="panel"><h2>点名时间</h2>${timeline.length?timeline.map(x=>{const s=state.students.find(st=>st.id===x.studentId);return `<div class="stat-row"><span><strong>${esc(s?.displayName||s?.name||x.studentId)}</strong><br><small class="hint">${esc(s?.className||x.className||'')}</small></span><span>${new Date(x.at).toLocaleString()}</span><span>难度 ${['','简单','适中','困难'][x.difficulty]||'—'}</span></div>`}).join(''):'<div class="empty">暂无点名记录</div>'}</div>`:`<div class="panel"><h2>学生总点名次数</h2>${rows.length?rows.map(s=>`<div class="stat-row"><span><strong>${esc(s.displayName||s.name)}</strong><br><small class="hint">${esc(s.className)}</small></span><span>${counts.get(s.id)||0}次</span><span class="hint">${s.focus?'关注':''}</span></div>`).join(''):'<div class="empty">导入学生后显示统计</div>'}</div>`}`;$('#timelineBtn')?.addEventListener('click',()=>{state.statsMode='timeline';renderHistory();});$('#countsBtn')?.addEventListener('click',()=>{state.statsMode='counts';renderHistory();});$('#historyWindow')?.addEventListener('change',async e=>{state.settings.historyWindow=e.target.value==='all'?999999:Number(e.target.value);await DB.put({id:'main',...state.settings});renderHistory();});}
function renderData(){$('#view-data').innerHTML=`<div class="panel"><h2>导入成绩文件</h2><p class="hint">支持“数智作业”与“学生小题得分明细”两类 xlsx。每次导入都会新增一条考试记录，不覆盖之前的考试。</p><input id="xlsxInput" class="file-input" type="file" accept=".xlsx"><div id="importResult"></div></div><div class="panel"><h2>已导入考试 <span class="badge">${state.exams.length}次</span></h2>${state.exams.length?state.exams.sort((a,b)=>String(b.date).localeCompare(String(a.date))).map(e=>`<div class="stat-row"><span><strong>${esc(e.name)}</strong><br><small class="hint">考试日期：${esc(e.date)}</small></span><span><small class="hint">记录人数：${e.count||0}人</small><br><small class="hint">文件：${esc(e.sourceFile||'')}</small></span><span></span></div>`).join(''):'<div class="empty">尚未导入考试</div>'}</div><div class="panel"><h2>备份与恢复</h2><div class="actions"><button class="secondary" id="backupBtn">导出完整备份</button><button class="secondary" id="historyExportBtn">导出点名历史</button><label class="secondary" style="text-align:center">选择备份<input id="backupInput" type="file" accept=".json" hidden></label></div><p class="hint">备份包含学生资料、考试记录、设置、缺席标记和点名历史。</p></div><div class="panel"><h2>清除数据</h2><p class="hint danger-text">清除后无法从本机恢复，请先导出备份。</p><button class="danger" id="clearBtn">清除全部本地数据</button></div>`;$('#xlsxInput')?.addEventListener('change',handleImport);$('#backupBtn')?.addEventListener('click',exportBackup);$('#historyExportBtn')?.addEventListener('click',exportHistory);$('#backupInput')?.addEventListener('change',handleRestore);$('#clearBtn')?.addEventListener('click',clearAll);}
async function handleImport(e){const file=e.target.files[0];if(!file)return;const box=$('#importResult');box.textContent='正在读取…';try{const result=await importGrades(file);if(!result.students.length){box.innerHTML='<p class="danger-text">未识别到学生记录，请检查文件格式。</p>';return;}state.pendingImport={file,result};box.innerHTML=`<div class="panel"><h3>请确认考试信息</h3><div class="grid"><div class="field"><label>考试名称</label><input id="examName" value="${esc(result.source.exercise)}"></div><div class="field"><label>考试时间</label><input id="examDate" type="date" value="${esc(result.source.date)}"></div><div class="field"><label>考试总分</label><input id="examTotalScore" type="number" min="1" step="0.01" value="${Number(result.totalScore)||100}"></div></div><p class="hint">识别到 ${result.students.length} 条记录。请确认考试名称、时间和总分后保存。</p><button class="primary" id="saveExamBtn">确认并保存考试</button>${result.warnings.length?`<p class="hint danger-text">提示：${result.warnings.slice(0,8).map(esc).join('；')}${result.warnings.length>8?'…':''}</p>`:''}</div>`;$('#saveExamBtn').addEventListener('click',savePendingExam);}catch(err){box.innerHTML=`<p class="danger-text">读取失败：${esc(err.message)}</p>`;}}
async function savePendingExam(){const pending=state.pendingImport;if(!pending)return;const name=$('#examName').value.trim()||pending.result.source.exercise;const date=$('#examDate').value||pending.result.source.date;const examId=`exam-${Date.now()}-${Math.random().toString(36).slice(2,7)}`;const exam={id:examId,name,date,sourceFile:pending.file.name,importedAt:new Date().toISOString(),count:pending.result.students.length};await DB.put('exams',exam);for(const incoming of pending.result.students){const base=identityBase(incoming),old=state.students.find(s=>s.id===incoming.id)||(incoming.id===base?state.students.find(s=>s.id===base):null);await DB.put('examResults',{id:`${examId}:${incoming.id}`,examId,studentId:incoming.id,identityKey:incoming.identityKey||incoming.id,result:incoming});await DB.put('students',old?{...old,...incoming,focus:old.focus===true}:incoming);}state.pendingImport=null;await reload();toast(`已保存考试：${name}`);}
async function handleRestore(e){const file=e.target.files[0];if(!file)return;try{const data=JSON.parse(await file.text());if(!data||!Array.isArray(data.students)||!Array.isArray(data.history))throw new Error('备份文件结构不完整');if(!confirm('恢复备份会覆盖当前本地数据，确定继续吗？'))return;for(const key of ['students','history','settings','absences','meta','exams','examResults'])await DB.replace(key,Array.isArray(data[key])?data[key]:[]);await reload();toast('备份已恢复');}catch(err){toast(`恢复失败：${err.message}`);}}
async function clearAll(){if(!confirm('确定清除全部学生、考试、历史和设置吗？此操作不可撤销。'))return;for(const key of ['students','history','settings','absences','meta','exams','examResults'])await DB.clear(key);state.currentClass='';state.candidates=[];await reload();toast('本地数据已清除');}
function renderSettings(){$('#view-settings').innerHTML=`<div class="panel"><h2>点名参数</h2><p class="hint">候选人数、三档难度匹配和快捷班级都会保存到本机。</p><div class="grid three"><div class="field"><label>候选人数</label><input data-setting="candidateCount" type="number" min="1" max="12" value="${state.settings.candidateCount}"></div>${[['recentDecay','近期衰减强度',0.1,0.95,0.01],['recoveryPerCall','冷却恢复速度',0.02,0.5,0.01],['focusBoost','特别关注加权',1,3,0.05],['topScoreSuppression','高分首轮抑制',0.3,1,0.05],['strongerStep','换人时提高要求',0.05,0.5,0.01],['historyWindow','最近点名统计窗口',5,200,1]].map(([k,l,min,max,step])=>`<div class="field"><label>${l}</label><input data-setting="${k}" type="number" min="${min}" max="${max}" step="${step}" value="${state.settings[k]}"></div>`).join('')}</div><div class="actions"><button class="primary" id="saveSettings">保存设置</button><button class="secondary" id="resetSettings">恢复默认</button></div></div><div class="panel"><h2>难度匹配目标</h2><div class="grid">${[1,2,3].map(i=>`<div class="field"><label>${['简单','适中','困难'][i-1]}：目标成绩 / 匹配范围</label><div style="display:flex;gap:6px"><input data-diff="${i}" data-key="target" type="number" min="0" max="100" value="${state.settings.difficulty[i].target}"><input data-diff="${i}" data-key="spread" type="number" min="5" max="60" value="${state.settings.difficulty[i].spread}"></div></div>`).join('')}</div></div><div class="panel"><h2>快捷班级</h2><p class="hint">输入班级编号，用逗号分隔，例如：01,02,10。页面顶部会生成快捷按钮，点击可循环切换班级。</p><input id="shortcutClasses" value="${esc((state.settings.shortcutClasses||[]).join(','))}" placeholder="01,02,10"><button class="primary" id="saveShortcuts">保存快捷班级</button></div>`;$('#saveSettings').addEventListener('click',saveSettings);$('#resetSettings').addEventListener('click',async()=>{state.settings=mergeConfig();await DB.put({id:'main',...state.settings});renderSettings();toast('已恢复默认参数');});$('#saveShortcuts').addEventListener('click',async()=>{state.settings.shortcutClasses=$('#shortcutClasses').value.split(/[,，\s]+/).map(v=>normalizeClassName(v)).filter((v,i,a)=>v&&a.indexOf(v)===i);await DB.put({id:'main',...state.settings});render();toast('快捷班级已保存');});}
async function saveSettings(){const next={...state.settings};$$('[data-setting]').forEach(el=>next[el.dataset.setting]=el.tagName==='SELECT'?el.value:Number(el.value));$$('[data-diff]').forEach(el=>next.difficulty[el.dataset.diff][el.dataset.key]=Number(el.value));state.settings=mergeConfig(next);await DB.put({id:'main',...state.settings});toast('设置已保存');}
