function renderSettings(){$('#view-settings').innerHTML=`<div class="panel"><h2>点名参数</h2><p class="hint">候选人数、近期冷却、特别关注和三档班级位次区间都会保存到本机。</p><div class="grid three"><div class="field"><label>候选人数</label><input data-setting="candidateCount" type="number" min="1" max="12" value="${state.settings.candidateCount}"></div>${[['recentDecay','近期衰减强度',0.1,0.95,0.01],['recoveryPerCall','冷却恢复速度',0.02,0.5,0.01],['focusBoost','特别关注加权',1,3,0.05],['historyWindow','最近点名统计窗口',5,200,1]].map(([k,l,min,max,step])=>`<div class="field"><label>${l}</label><input data-setting="${k}" type="number" min="${min}" max="${max}" step="${step}" value="${state.settings[k]}"></div>`).join('')}</div><div class="actions"><button class="primary" id="saveSettings">保存设置</button><button class="secondary" id="resetSettings">恢复默认</button></div></div><div class="panel"><h2>班级位次难度区间</h2><p class="hint">简单：60%-100%，适中：25%-75%，困难：0%-35%。边界向上取整，候选只会从对应区间内抽取。</p></div><div class="panel"><h2>快捷班级</h2><p class="hint">输入班级编号，用逗号分隔，例如：01,02,10。</p><input id="shortcutClasses" value="${esc((state.settings.shortcutClasses||[]).join(','))}" placeholder="01,02,10"><button class="primary" id="saveShortcuts">保存快捷班级</button></div>`;$('#saveSettings').addEventListener('click',saveSettings);$('#resetSettings').addEventListener('click',async()=>{state.settings=mergeConfig();await DB.put({id:'main',...state.settings});renderSettings();toast('已恢复默认参数');});$('#saveShortcuts').addEventListener('click',async()=>{state.settings.shortcutClasses=$('#shortcutClasses').value.split(/[,，\\s]+/).map(v=>normalizeClassName(v)).filter((v,i,a)=>v&&a.indexOf(v)===i);await DB.put({id:'main',...state.settings});render();toast('快捷班级已保存');});}
